from PIL import Image
import numpy as np
im=np.asarray(Image.open('first_frame.png').convert('RGB'))
# print dominant-color runs on key rows and columns
for y in [0,20,40,50,60,70,80,90,100,110,120,130,140]:
 row=im[y]
 # quantize to /16 and runs >2
 q=(row//24)*24
 runs=[]; s=0
