  if x==256 or not np.array_equal(q[x] if x<256 else None,q[s]):
   if x-s>=3:runs.append((s,x-1,tuple(q[s])))
   s=x
 print('ROW',y,runs[:40])
print('cols')
for x in [0,20,40,60,80,100,120,128,140,160,180,200,220,240,255]:
